UPDATE alert_record
SET status = 'RECOVERED',
    recovered_at = #{recoveredAt,jdbcType=TIMESTAMP},
    updated_at = #{recoveredAt,jdbcType=TIMESTAMP}
WHERE id = #{id}
  AND status <> 'RECOVERED'

